#!/usr/bin/env python3
"""Measure preset coverage using primary colors generated by Matugen 4.2.0.

This deliberately feeds source colors into Matugen first. It never treats the
source colors themselves as Matugen output.
"""

from __future__ import annotations

import argparse
import colorsys
import json
import math
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any

from color_match import (
    NEAREST_PRESET_WARNING_DELTA_E,
    delta_e_hex,
    find_closest_theme,
    hex_to_lab,
)

MATUGEN_VERSION = "4.2.0"
SCHEME_TYPES = (
    "scheme-content",
    "scheme-expressive",
    "scheme-fidelity",
    "scheme-fruit-salad",
    "scheme-monochrome",
    "scheme-neutral",
    "scheme-rainbow",
    "scheme-tonal-spot",
    "scheme-vibrant",
    "scheme-smart",
)
HUES = tuple(range(0, 360, 15))
SATURATIONS = (0.35, 0.65, 0.95)
LIGHTNESSES = (0.30, 0.50, 0.70)


def source_colors() -> list[tuple[int, str]]:
    """Return a deterministic HSL grid of seed colors for Matugen."""
    result = []
    for hue in HUES:
        for saturation in SATURATIONS:
            for lightness in LIGHTNESSES:
                red, green, blue = colorsys.hls_to_rgb(
                    hue / 360.0, lightness, saturation
                )
                color = "#{:02x}{:02x}{:02x}".format(
                    round(red * 255), round(green * 255), round(blue * 255)
                )
                result.append((hue, color))
    return result


def extract_primary_colors(payload: dict[str, Any]) -> dict[str, str]:
    """Read the dark and light semantic primary roles from Matugen JSON."""
    try:
        primary = payload["colors"]["primary"]
        extracted = {
            mode: primary[mode]["color"]
            for mode in ("dark", "light")
        }
    except (KeyError, TypeError) as exc:
        raise ValueError(
            "Matugen JSON is missing colors.primary.dark.color and/or "
            "colors.primary.light.color"
        ) from exc

    for mode, color in extracted.items():
        if not isinstance(color, str) or not re.fullmatch(
            r"#[0-9a-fA-F]{6}", color
        ):
            raise ValueError(f"Invalid Matugen {mode} primary color: {color!r}")
    return extracted


def run_matugen(
    executable: str, source_hex: str, scheme_type: str
) -> dict[str, str]:
    command = [
        executable,
        "color",
        "hex",
        source_hex,
        "--type",
        scheme_type,
        "--json",
        "hex",
        "--dry-run",
        "--quiet",
    ]
    completed = subprocess.run(
        command, check=True, capture_output=True, text=True, timeout=30
    )
    try:
        payload = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        raise RuntimeError(
            f"Matugen did not return JSON for {source_hex} / {scheme_type}: "
            f"{completed.stdout[:300]!r}; stderr={completed.stderr[:300]!r}"
        ) from exc
    return extract_primary_colors(payload)


def percentile(values: list[float], fraction: float) -> float:
    if not values:
        raise ValueError("Cannot calculate a percentile from an empty sample")
    ordered = sorted(values)
    position = (len(ordered) - 1) * fraction
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return ordered[lower]
    weight = position - lower
    return ordered[lower] * (1 - weight) + ordered[upper] * weight


def primary_hue_chroma_region(color_hex: str) -> str:
    """Bucket a generated primary by CIELAB hue angle and chroma."""
    _, a, b = hex_to_lab(color_hex)
    chroma = math.hypot(a, b)
    if chroma < 10:
        hue_band = "neutral"
    else:
        hue = math.degrees(math.atan2(b, a)) % 360
        lower = int(hue // 30) * 30
        hue_band = f"{lower:03d}-{lower + 30:03d}°"

    if chroma < 10:
        chroma_band = "0-10"
    elif chroma < 25:
        chroma_band = "10-25"
    elif chroma < 40:
        chroma_band = "25-40"
    elif chroma < 55:
        chroma_band = "40-55"
    else:
        chroma_band = "55+"
    return f"{hue_band} / C* {chroma_band}"



def primary_hue_chroma_region(color_hex: str) -> str:
    """Bucket a generated primary by CIELAB hue angle and chroma."""
    _, a, b = hex_to_lab(color_hex)
    chroma = math.hypot(a, b)
    if chroma < 10:
        hue_band = "neutral"
    else:
        hue = math.degrees(math.atan2(b, a)) % 360
        lower = int(hue // 30) * 30
        hue_band = f"{lower:03d}-{lower + 30:03d}°"

    if chroma < 10:
        chroma_band = "0-10"
    elif chroma < 25:
        chroma_band = "10-25"
    elif chroma < 40:
        chroma_band = "25-40"
    elif chroma < 55:
        chroma_band = "40-55"
    else:
        chroma_band = "55+"
    return f"{hue_band} / C* {chroma_band}"


def summarize(values: list[float]) -> dict[str, float]:
    return {
        "median": percentile(values, 0.50),
        "p90": percentile(values, 0.90),
        "p95": percentile(values, 0.95),
        "max": max(values),
        "mean": sum(values) / len(values),
    }


def analyze(
    matugen: str, themes_path: Path
) -> dict[str, Any]:
    themes = json.loads(themes_path.read_text(encoding="utf-8"))
    material_themes = {
        name: colors for name, colors in themes.items() if name != "Classic"
    }
    if len(material_themes) != 56:
        raise ValueError(
            f"Expected 56 Material palette variants, found {len(material_themes)}"
        )

    version = subprocess.run(
        [matugen, "--version"],
        check=True,
        capture_output=True,
        text=True,
        timeout=15,
    ).stdout.strip()
    if MATUGEN_VERSION not in version:
        raise RuntimeError(
            f"This report is pinned to Matugen {MATUGEN_VERSION}; found {version!r}"
        )

    samples: list[dict[str, Any]] = []
    for hue, source_hex in source_colors():
        for scheme_type in SCHEME_TYPES:
            generated = run_matugen(matugen, source_hex, scheme_type)
            for mode, primary_hex in generated.items():
                nearest_name, weighted_score = find_closest_theme(
                    primary_hex, themes
                )
                primary_name = min(
                    material_themes,
                    key=lambda name: delta_e_hex(
                        primary_hex, material_themes[name]["primary"]
                    ),
                )
                primary_score = delta_e_hex(
                    primary_hex, material_themes[primary_name]["primary"]
                )
                samples.append(
                    {
                        "source_hue": hue,
                        "source_hex": source_hex,
                        "scheme_type": scheme_type,
                        "mode": mode,
                        "primary_hex": primary_hex,
                        "nearest_primary_theme": primary_name,
                        "primary_delta_e00": primary_score,
                        "matcher_theme": nearest_name,
                        "matcher_score": weighted_score,
                    }
                )

    primary_values = [item["primary_delta_e00"] for item in samples]
    matcher_values = [item["matcher_score"] for item in samples]
    by_scheme_mode: dict[str, list[float]] = defaultdict(list)
    by_hue: dict[str, list[float]] = defaultdict(list)
    by_generated_region: dict[str, list[float]] = defaultdict(list)
    matcher_winners: Counter[str] = Counter()
    for item in samples:
        by_scheme_mode[f'{item["scheme_type"]}/{item["mode"]}'].append(
            item["primary_delta_e00"]
        )
        by_hue[f'{(item["source_hue"] // 30) * 30:03d}°'].append(
            item["primary_delta_e00"]
        )
        by_generated_region[primary_hue_chroma_region(item["primary_hex"])].append(
            item["primary_delta_e00"]
        )
        matcher_winners[item["matcher_theme"]] += 1

    return {
        "matugen_version": version,
        "sampling": {
            "source_colors": len(source_colors()),
            "hue_step_degrees": 15,
            "saturations": list(SATURATIONS),
            "hsl_lightnesses": list(LIGHTNESSES),
            "scheme_types": list(SCHEME_TYPES),
            "modes": ["dark", "light"],
            "palette_candidates_for_primary_fidelity": 56,
            "palette_candidates_for_live_matcher": len(themes),
            "sample_count": len(samples),
            "note": (
                "Each HSL seed is passed through Matugen 4.2.0's color command. "
                "The generated semantic primary roles are measured; seed RGB "
                "values are never compared directly to cursor presets. The "
                "dark/light roles are read from one generated JSON result."
            ),
        },
        "primary_fidelity_delta_e00": summarize(primary_values),
        "current_matcher_score": summarize(matcher_values),
        "matcher_warning_threshold": NEAREST_PRESET_WARNING_DELTA_E,
        "matcher_samples_above_warning_threshold": sum(
            score > NEAREST_PRESET_WARNING_DELTA_E for score in matcher_values
        ),
        "primary_fidelity_by_scheme_and_mode": {
            key: summarize(values) for key, values in sorted(by_scheme_mode.items())
        },
        "primary_fidelity_by_source_hue_band": {
            key: summarize(values) for key, values in sorted(by_hue.items())
        },
        "primary_fidelity_by_generated_hue_chroma_region": {
            key: summarize(values)
            for key, values in sorted(by_generated_region.items())
        },
        "matcher_theme_selection_counts": dict(matcher_winners.most_common()),
        "worst_primary_matches": sorted(
            samples, key=lambda item: item["primary_delta_e00"], reverse=True
        )[:15],
        "samples": samples,
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--matugen", default="matugen", help="Matugen 4.2.0 executable")
    parser.add_argument(
        "--themes",
        type=Path,
        default=Path(__file__).resolve().parent.parent / "themes.json",
    )
    parser.add_argument(
        "--json-output",
        type=Path,
        help="Optional path for the complete machine-readable report",
    )
    args = parser.parse_args()

    try:
        report = analyze(args.matugen, args.themes)
    except (OSError, subprocess.SubprocessError, ValueError, RuntimeError) as exc:
        print(f"Matugen coverage analysis failed: {exc}", file=sys.stderr)
        return 1

    primary = report["primary_fidelity_delta_e00"]
    matcher = report["current_matcher_score"]
    print(f'Matugen: {report["matugen_version"]}')
    print(f'Samples: {report["sampling"]["sample_count"]}')
    print(
        "Primary-only ΔE00: "
        f'median {primary["median"]:.2f}, p90 {primary["p90"]:.2f}, '
        f'p95 {primary["p95"]:.2f}, worst {primary["max"]:.2f}'
    )
    print(
        "Current 75/25 matcher score: "
        f'median {matcher["median"]:.2f}, p90 {matcher["p90"]:.2f}, '
        f'p95 {matcher["p95"]:.2f}, worst {matcher["max"]:.2f}'
    )
    print(
        "Matcher warnings: "
        f'{report["matcher_samples_above_warning_threshold"]}/'
        f'{report["sampling"]["sample_count"]} above '
        f'{report["matcher_warning_threshold"]:.0f}'
    )
    print("Worst primary matches:")
    for item in report["worst_primary_matches"]:
        print(
            f'  {item["primary_delta_e00"]:5.2f} ΔE00  '
            f'{item["scheme_type"]:<20} {item["mode"]:<5} '
            f'{item["source_hex"]} -> {item["primary_hex"]} '
            f'nearest={item["nearest_primary_theme"]}'
        )

    if args.json_output:
        args.json_output.parent.mkdir(parents=True, exist_ok=True)
        args.json_output.write_text(
            json.dumps(report, indent=2) + "\n", encoding="utf-8"
        )
        print(f"Full report: {args.json_output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
